gi,go=G['Demo pair 1 input'],G['Demo pair 1 output']
H,W=len(gi),len(gi[0])
# hypothesis: per column, the non-1 value forms a contiguous downward run in output starting from row where it's last seen? Print column-wise runs.
for c in range(W):
    col=[gi[r][c] for r in range(H)]
    # run lengths of non-1 values
    runs=[];prev=None;s=[]
    for r,v in enumerate(col):
        if v!=1 and prev is None: s=[r]; prev=v
        elif v==prev: s.append(r)
        else: 
            if s:runs.append((s[0],s[-1],v))
            prev=v; s=[r]
    if s:runs.append((s[0],s[-1],prev))
    print(c,[x for x in runs][:4], 'nruns',sum(1 for x in runs if x[0]<x[2]))

# print output columns for a few cols to see the shape: which rows changed and what fill pattern is
for c in [0,1,2,3,5,19]:
    col=[go[r][c] for r in range(H)]
    print('col',c)
    for r,v in enumerate(col):
        if v!=1: print(r,'.',v)

